"""Check a PDB's source documents against a clone of the declared commit.

Usage: python3 -I srccheck.py REPORT CLONE PREFIX

REPORT is dllreport.cs's output for the published DLL; its "document:" lines
give each source file's path and checksum as the publisher compiled it.
PREFIX is the mapped source root in those paths (usually /_/). For each
document under PREFIX that git tracks in CLONE, it compares the checksum with
the file as checked out and with the same bytes using CRLF line
endings. Documents git does not track (generated by the SDK or by source
generators, or missing) are listed apart; they can only be checked against
our own build's PDB.

Written 21 October 2026 for the nupkg pilot.
"""
import collections, hashlib, os, subprocess, sys

report, clone, prefix = sys.argv[1:4]
tracked = set(subprocess.run(['git', '-C', clone, 'ls-files', '-z'], capture_output=True, check=True).stdout.decode().split('\0'))
count = collections.Counter()
for line in open(report, encoding='utf-8'):
    if not line.startswith('document: '): continue
    rest = line[len("document: "):].rstrip("\n").split(" embedded")[0]
    path, alg, digest = rest.rsplit(' ', 2)
    rel = path[len(prefix):].replace('\\', '/') if path.startswith(prefix) else None
    if rel is None or rel not in tracked:
        state = 'not tracked'
    else:
        data = open(os.path.join(clone, rel), 'rb').read()
        crlf = data.replace(b'\r\n', b'\n').replace(b'\n', b'\r\n')
        h = lambda b: hashlib.new(alg, b).hexdigest()
        state = 'as checked out' if h(data) == digest else 'with CRLF' if h(crlf) == digest else 'NO MATCH'
    count[state] += 1
    print(f"{state:14} {path}")
print('summary: ' + ', '.join(f'{k} {v}' for k, v in sorted(count.items())))
